import base64
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / '09_TestGuide'
OUT.mkdir(exist_ok=True)
rules = json.loads((ROOT / '06_UnityFramework/Assets/Config/Runtime/RecoveredRules.json').read_text(encoding='utf-8-sig'))
report_path = ROOT / '07_Verification/gm_workflow_validation.json'
report = json.loads(report_path.read_text(encoding='utf-8-sig')) if report_path.exists() else {'passed': False, 'checks': [], 'error': '本轮验证尚未完成'}
images = {}
for key, name in [('gmProgress','gm_progress_tools.png'),('gmEvents','gm_event_tools.png'),('reward','reward_amount_centered.png'),('result','gm_withdrawal_all_tasks.png')]:
    path = ROOT / '07_Verification' / name
    if path.exists(): images[key] = 'data:image/png;base64,' + base64.b64encode(path.read_bytes()).decode()
data = json.dumps({'rules': rules, 'report': report, 'images': images}, ensure_ascii=False).replace('</', '<\\/')
